insert into public.profile (id, name, title, tagline, summary, location, email, phone, whatsapp, linkedin, github, avatar_url, resume_url, updated_at) values (1, 'Kailash Rajkumar', 'Full-Stack Developer · Websites, CRM & Mobile Apps', 'I build business websites, CRM platforms, and mobile apps that work beautifully at scale.', 'I build high-performance websites for businesses across industries, custom CRM platforms, and mobile applications with Flutter or React Native. My work spans product design through delivery: responsive interfaces, reliable APIs, integrations, hosting, and secure infrastructure. I use powerful AI models, strong technical knowledge, and practical integrations to improve delivery speed while keeping client data, credentials, and production access protected.', 'Karama, Dubai, UAE', 'kailashrajkumar14@gmail.com', '+971 52 663 5447', '971526635447', 'https://linkedin.com/in/kailash-rajkumar', 'https://github.com/KailashRajkumar', null, null, '2026-09-26T09:20:17.228709+00:00');
